package com.example.arcana.client;
import com.example.arcana.network.*; import net.minecraft.client.gui.GuiGraphics; import net.minecraft.client.gui.components.Button; import net.minecraft.client.gui.screens.Screen; import net.minecraft.network.chat.Component;
public class SkillTreeScreen extends Screen {
 private int left,top;
 public SkillTreeScreen(){super(Component.literal("Arcana Skill Tree"));}
 protected void init(){left=width/2-185;top=height/2-130;addRenderableWidget(node("Attunement I",left+18,top+112,"attunement"));addRenderableWidget(node("Arcane Bolt",left+129,top+112,"bolt_range"));addRenderableWidget(node("Ward",left+240,top+112,null));addRenderableWidget(node("Blink",left+240,top+218,null));}
 private Button node(String label,int x,int y,String skill){return Button.builder(Component.literal(label),b->{if(skill!=null)ArcanaNetwork.CHANNEL.sendToServer(new UpgradeSkillPacket(skill));}).bounds(x,y,100,34).build();}
 public void render(GuiGraphics g,int mx,int my,float pt){renderBackground(g);int w=370,h=330;g.fill(left,top,left+w,top+h,0xE51A1420);g.fill(left+5,top+5,left+w-5,top+h-5,0xD92A2030);g.renderOutline(left,top,w,h,0xFF9A70C4);g.drawCenteredString(font,title,width/2,top+15,0xFFF0D8FF);g.drawString(font,"✦ Skill Points: 3",left+w-105,top+17,0xFFFFD56B);g.drawCenteredString(font,"CORE",width/2,top+49,0xFFFFFFFF);line(g,left+68,top+97,left+179,top+97,0xFF7C5BAA);line(g,left+190,top+97,left+291,top+97,0xFF7C5BAA);line(g,left+290,top+146,left+290,top+215,0xFF7C5BAA);icon(g,left+68,top+70,"✦",0xFF5BA7FF);icon(g,left+179,top+70,"⚡",0xFFB45CFF);icon(g,left+290,top+70,"◇",0xFF82E66A);icon(g,left+290,top+176,"◉",0xFF5CE7F2);g.drawString(font,"+10 max mana",left+18,top+154,0xFFBDB1C8);g.drawString(font,"+8 bolt range",left+129,top+154,0xFFBDB1C8);g.drawString(font,"Defense",left+247,top+154,0xFFA8F0B2);g.drawString(font,"Exploration",left+230,top+260,0xFF7EE6F4);g.fill(left+10,top+h-31,left+w-10,top+h-10,0xAA100C16);g.drawString(font,"Click a node to upgrade  •  ESC Close",left+18,top+h-24,0xFFE4D8F2);super.render(g,mx,my,pt);}
 private void icon(GuiGraphics g,int x,int y,String s,int c){g.drawCenteredString(font,s,x,y,c);}
 private void line(GuiGraphics g,int x1,int y1,int x2,int y2,int c){g.fill(Math.min(x1,x2),Math.min(y1,y2),Math.max(x1,x2)+2,Math.max(y1,y2)+2,c);}
}
